import sys
import sqlite3
import xml.etree.ElementTree as ET
from io import BytesIO

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    database = root.find('database').text
    table = root.find('table').text
    filters = []
    for filter_elem in root.findall('filter'):
        column = filter_elem.get('column')
        operator = filter_elem.get('operator')
        value = filter_elem.get('value')
        filters.append((column, operator, value))
    return database, table, filters

def build_query(database, table, filters):
    query = f"SELECT * FROM {table}"
    where_clause = []
    for column, operator, value in filters:
        if operator == 'eq':
            where_clause.append(f"{column} = ?")
        elif operator == 'gt':
            where_clause.append(f"{column} > ?")
        elif operator == 'lt':
            where_clause.append(f"{column} < ?")
        elif operator == 'like':
            where_clause.append(f"{column} LIKE ?")
        else:
            raise ValueError(f"Unsupported operator: {operator}")
    if where_clause:
        query += " WHERE " + " AND ".join(where_clause)
    return query

def execute_query(database_path, query, filters):
    conn = sqlite3.connect(database_path)
    cursor = conn.cursor()
    params = []
    for _, _, value in filters:
        params.append(value)
    cursor.execute(query, params)
    rows = cursor.fetchall()
    conn.close()
    return rows

def load_cache(cache_path):
    try:
        with open(cache_path, 'rb') as f:
            data = f.read()
        return eval(BytesIO(data).read())
    except (FileNotFoundError, SyntaxError):
        return None

def save_cache(cache_path, rows):
    with open(cache_path, 'wb') as f:
        f.write(str(rows).encode())

def main():
    if len(sys.argv) != 3:
        print("Usage: python report.py <config.xml> <cache.cache>")
        sys.exit(1)

    xml_path, cache_path = sys.argv[1], sys.argv[2]
    database, table, filters = parse_xml(xml_path)
    full_db_path = sys.path[0] + '/' + database

    if cache_path.endswith('.cache'):
        cache_path = cache_path[:-6]

    cache_rows = load_cache(cache_path)
    if cache_rows is not None:
        for row in cache_rows:
            print('\t'.join(str(val) if val is not None else '' for val in row))
    else:
        query = build_query(full_db_path, table, filters)
        rows = execute_query(full_db_path, query, filters)
        cache_rows = rows
        save_cache(cache_path, rows)
        for row in rows:
            print('\t'.join(str(val) if val is not None else '' for val in row))

if __name__ == "__main__":
    main()
